import { useMemo, useState, useCallback, useEffect } from 'react';
import type { Article, NavKey, SectionKey } from './data/types';
import { ARTICLES, INDICES, HOT_LIST, DATA_GLANCE } from './data/marketData';
import TopBar from './components/TopBar';
import IndexTape from './components/IndexTape';
import NewsList from './components/NewsList';
import SideRail from './components/SideRail';
import ArticleDetail from './components/ArticleDetail';
import SectionView from './components/SectionView';
import SearchResults from './components/SearchResults';
import './styles.css';

const NAV_ITEMS: { key: NavKey; label: string }[] = [
  { key: 'market', label: '市场行情' },
  { key: 'news', label: '资讯' },
  { key: 'deep', label: '深度分析' },
  { key: 'data', label: '数据工具' },
  { key: 'macro', label: '宏观观察' },
];

function articleMatches(a: Article, q: string): boolean {
  const k = q.trim().toLowerCase();
  if (!k) return true;
  return a.title.toLowerCase().includes(k) || a.summary.toLowerCase().includes(k);
}

export default function App() {
  const [nav, setNav] = useState<NavKey>('market');
  const [query, setQuery] = useState('');
  const [activeArticleId, setActiveArticleId] = useState<string | null>(null);

  const activeArticle = useMemo(
    () => ARTICLES.find((a) => a.id === activeArticleId) ?? null,
    [activeArticleId]
  );

  const filtered = useMemo(
    () => ARTICLES.filter((a) => articleMatches(a, query)),
    [query]
  );

  const handleNav = useCallback((key: NavKey) => {
    setNav(key);
    setActiveArticleId(null);
    setQuery('');
  }, []);

  const openArticle = useCallback((id: string) => {
    setActiveArticleId(id);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  const closeArticle = useCallback(() => {
    setActiveArticleId(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  useEffect(() => {
    if (!activeArticleId) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') closeArticle();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [activeArticleId, closeArticle]);

  const searchActive = query.trim().length > 0;

  return (
    <div className="app-shell">
      <TopBar
        nav={nav}
        navItems={NAV_ITEMS}
        onNav={handleNav}
        query={query}
        onQuery={setQuery}
      />

      <main className="page">
        <IndexTape indices={INDICES} />

        {activeArticle ? (
          <ArticleDetail
            article={activeArticle}
            related={ARTICLES.filter(
              (a) => a.id !== activeArticle.id && a.section === activeArticle.section
            ).concat(ARTICLES.filter((a) => a.id !== activeArticle.id && a.section !== activeArticle.section)).slice(0, 3)}
            onBack={closeArticle}
            onOpen={openArticle}
          />
        ) : searchActive ? (
          <SearchResults
            query={query.trim()}
            results={filtered}
            onOpen={openArticle}
            onClear={() => setQuery('')}
          />
        ) : nav === 'market' || nav === 'news' ? (
          <div className="two-col">
            <section className="col-main">
              <NewsList
                articles={filtered}
                onOpen={openArticle}
                heading={nav === 'market' ? '财经要闻' : '最新资讯'}
              />
            </section>
            <aside className="col-rail">
              <SideRail hotList={HOT_LIST} dataGlance={DATA_GLANCE} onOpen={openArticle} />
            </aside>
          </div>
        ) : (
          <SectionView
            nav={nav}
            articles={ARTICLES.filter((a) => a.section === (nav as SectionKey))}
            onOpen={openArticle}
          />
        )}
      </main>

      <footer className="site-foot">
        <p>金衡财经 · 财经资讯与市场观察示例站</p>
        <p className="foot-note">页面内行情与资讯均为本地示例数据，不构成投资建议，不代表实时行情。</p>
      </footer>
    </div>
  );
}

