  background: var(--panel); border: 1px dashed var(--line); border-radius: var(--radius);
  padding: 44px 20px; text-align: center;
}
.empty strong { display: block; font-size: 16px; margin-bottom: 6px; }
.empty span { color: var(--muted); font-size: 13.5px; }

/* ---------- footer ---------- */
.site-foot { border-top: 1px solid var(--line-soft); padding: 20px 22px; text-align: center; }
.site-foot p { margin: 0; font-size: 12.5px; color: var(--muted); }
.site-foot .foot-note { font-size: 11.5px; color: var(--faint); margin-top: 4px; }

/* ---------- responsive ---------- */
@media (max-width: 1080px) {
  .tape-grid { grid-template-columns: repeat(3, minmax(0,1fr)); }
  .two-col { grid-template-columns: minmax(0,1fr) 290px; gap: 20px; }
}

@media (max-width: 860px) {
  .topbar-inner { flex-wrap: wrap; gap: 10px; padding: 10px 16px; }
  .main-nav { order: 3; flex-basis: 100%; }
  .search { width: 100%; order: 4; }
  .page { padding: 16px 16px 40px; }
  .two-col { grid-template-columns: minmax(0,1fr); }
  .col-rail { position: static; }
  .section-grid { grid-template-columns: 1fr; }
  .kd-grid { grid-template-columns: 1fr 1fr; }
  .art-title { font-size: 22px; }
  .tape-grid {
    display: flex;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    padding-bottom: 4px;
    gap: 10px;
    -webkit-overflow-scrolling: touch;
  }
  .tape-grid::-webkit-scrollbar { height: 6px; }
  .tape-grid::-webkit-scrollbar-thumb { background: var(--line); border-radius: 3px; }
  .index-card { flex: 0 0 200px; scroll-snap-align: start; }
}

@media (max-width: 560px) {
  .news-item { grid-template-columns: 1fr; gap: 8px; padding: 13px; }
  .ni-meta { flex-direction: row; flex-wrap: wrap; align-items: center; gap: 8px; }
  .ni-title { font-size: 15.5px; }
  .brand-name span { display: none; }
  .kd-grid { grid-template-columns: 1fr; }
  .art-body { font-size: 15px; }
  .index-card { flex: 0 0 180px; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; scroll-behavior: auto !important; }
}

