import type { NavKey, SectionKey } from '../data/types';

type Props = {
  nav: NavKey;
  navItems: { key: NavKey; label: string }[];
  onNav: (key: NavKey) => void;
  query: string;
  onQuery: (q: string) => void;
};

type BaseBarProps = Omit<Props, 'nav' | 'onNav' | 'navItems'>;

function useNavBase() {
  return null;
}

export default function TopBar({ nav, navItems, onNav, query, onQuery }: Props) {
  return (
    <header className="topbar">
      <div className="topbar-inner">
        <div className="brand">
          <div className="brand-mark">金</div>
          <div className="brand-name">
            <strong>金衡财经</strong>
            <span>JINHENG FINANCE</span>
          </div>
        </div>

        <nav className="main-nav" aria-label="主导航">
          {navItems.map((item) => (
            <button
              key={item.key}
              type="button"
              className={'nav-btn' + (nav === item.key ? ' is-active' : '')}
              aria-current={nav === item.key ? 'page' : undefined}
              onClick={() => onNav(item.key)}
            >
              {item.label}
            </button>
          ))}
        </nav>

        <div className="search" role="search">
          <span className="search-icon" aria-hidden="true">
            <svg width="15" height="15" viewBox="0 0 16 16" fill="none">
              <circle cx="7" cy="7" r="5" stroke="currentColor" strokeWidth="1.5" />
              <path d="M11 11l3 3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
            </svg>
          </span>
          <input
            type="search"
            value={query}
            onChange={(e) => onQuery(e.target.value)}
            placeholder="搜索资讯标题"
            aria-label="搜索资讯标题"
          />
          {query && (
