import type { IndexQuote } from '../data/types';

function fmtValue(v: number) {
  return v.toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function fmtPct(v: number) {
  return (v > 0 ? '+' : '') + v.toFixed(2) + '%';
}
function trendClass(v: number) {
  return v > 0 ? 'pos' : v < 0 ? 'neg' : 'neu';
}

function Spark({ data, up, id }: { data: number[]; up: boolean; id: string }) {
  const w = 120;
  const h = 34;
  const min = Math.min(...data);
  const max = Math.max(...data);
  const span = max - min || 1;
  const pts = data.map((d, i) => {
    const x = (i / (data.length - 1)) * w;
    const y = h - 2 - ((d - min) / span) * (h - 4);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  });
  const stroke = up ? 'var(--up)' : 'var(--down)';
  const gid = 'spark-' + id;
  return (
    <svg className="ic-spark" viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" aria-hidden="true">
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={stroke} stopOpacity="0.28" />
          <stop offset="100%" stopColor={stroke} stopOpacity="0" />
        </linearGradient>
      </defs>
      <polygon points={`0,${h} ${pts.join(' ')} ${w},${h}`} fill={`url(#${gid})`} />
      <polyline points={pts.join(' ')} fill="none" stroke={stroke} strokeWidth="1.6" strokeLinejoin="round" strokeLinecap="round" />
    </svg>
  );
}

export default function IndexTape({ indices }: { indices: IndexQuote[] }) {
  return (
    <section className="index-tape" aria-label="核心指数行情">
      <div className="tape-head">
        <h1 className="tape-title">
          <em>行情</em>核心指数
        </h1>
        <span className="tape-note">示例数据 · 非实时行情</span>
      </div>
      <div className="tape-grid">
        {indices.map((idx) => (
          <div
            key={idx.code}
            className="index-card"
            aria-label={`${idx.name} 当前 ${fmtValue(idx.value)}，涨跌幅 ${fmtPct(idx.changePct)}`}
          >
            <div className="ic-name">
              <span>{idx.name}</span>
              <span className="ic-code">{idx.code}</span>
            </div>
            <div className="ic-value">{fmtValue(idx.value)}</div>
            <div className={'ic-change ' + trendClass(idx.changePct)}>
              {idx.change > 0 ? '+' : ''}
              {idx.change.toFixed(2)}　{fmtPct(idx.changePct)}
            </div>
            <Spark data={idx.spark} up={idx.changePct >= 0} id={idx.code} />
          </div>
        ))}
      </div>
    </section>
  );
}

